  function saveAsTemplate(){const field=$("template-name"),name=field.value.trim()||`${$("doc-title").value.trim()||"未命名文件"} 模板`;state.templates.push({id:uid(),name,blocks:clone(state.blocks),orientation:state.orientation,pageCount:state.pageCount,headerText:state.headerText,footerText:state.footerText,showPageNumber:state.showPageNumber,pageNumberAlign:state.pageNumberAlign,createdAt:new Date().toLocaleDateString("zh-TW"),builtIn:false});saveTemplateStore();field.value="";renderTemplates();notify(`已儲存模板「${name}」`)}
  function updateEditingUI(){const editing=!!state.editingTemplateId;$("save-template-changes").hidden=!editing;$("save-status").textContent=editing?"正在編輯模板":"已自動儲存";document.body.classList.toggle("editing-template",editing)}
  function applyTemplateMeta(template){state.pageCount=Math.max(1,+template.pageCount||1);state.currentPage=0;state.headerText=template.headerText||"";state.footerText=template.footerText||"";state.showPageNumber=template.showPageNumber!==false;state.pageNumberAlign=template.pageNumberAlign||"right";$("header-text").value=state.headerText;$("footer-text").value=state.footerText;$("show-page-number").checked=state.showPageNumber;$("page-number-align").value=state.pageNumberAlign}
