  function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
  function exportWord(){try{const title=$("doc-title").value||"A4文件",bytes=window.PaperGridDocx.buildDocx(state.blocks,title,{width:PAGE_W,height:PAGE_H,pageCount:state.pageCount,headerText:state.headerText,footerText:state.footerText,showPageNumber:state.showPageNumber,pageNumberAlign:state.pageNumberAlign});download(new Blob([bytes],{type:"application/vnd.openxmlformats-officedocument.wordprocessingml.document"}),`${title}.docx`);notify(`Word DOCX 已匯出（${state.pageCount} 頁）`)}catch(error){console.error(error);notify("Word 匯出失敗")}}
  function wrapText(ctx,text,maxWidth){const lines=[];text.split("\n").forEach(paragraph=>{if(paragraph===""){lines.push("");return}let line="";for(const char of paragraph){const test=line+char;if(ctx.measureText(test).width>maxWidth&&line){lines.push(line);line=char}else line=test}lines.push(line)});return lines}
