  function drawImageInBox(ctx,image,rx,ry,rw,rh,scale,padding=0,fit="contain",positionX=50,positionY=50){const boxW=Math.max(1,rw-padding*2),boxH=Math.max(1,rh-padding*2),ratio=fit==="cover"?Math.max(boxW/image.naturalWidth,boxH/image.naturalHeight):Math.min(boxW/image.naturalWidth,boxH/image.naturalHeight),dw=image.naturalWidth*ratio,dh=image.naturalHeight*ratio,dx=rx+padding+(boxW-dw)*(positionX/100),dy=ry+padding+(boxH-dh)*(positionY/100);ctx.save();ctx.beginPath();ctx.rect((rx+padding)*scale,(ry+padding)*scale,boxW*scale,boxH*scale);ctx.clip();ctx.drawImage(image,dx*scale,dy*scale,dw*scale,dh*scale);ctx.restore()}
  function drawPageDecorations(ctx,pageIndex,scale){ctx.save();ctx.fillStyle="#6f7d83";ctx.strokeStyle="#dbe2e3";ctx.lineWidth=scale;ctx.font=`${10*scale}px "Noto Sans TC",sans-serif`;ctx.textBaseline="middle";if(state.headerText){ctx.fillText(state.headerText,56*scale,32*scale);ctx.beginPath();ctx.moveTo(56*scale,45*scale);ctx.lineTo((PAGE_W-56)*scale,45*scale);ctx.stroke()}if(state.footerText||state.showPageNumber){const y=(PAGE_H-30)*scale;ctx.beginPath();ctx.moveTo(56*scale,(PAGE_H-43)*scale);ctx.lineTo((PAGE_W-56)*scale,(PAGE_H-43)*scale);ctx.stroke();if(state.footerText)ctx.fillText(state.footerText,56*scale,y);if(state.showPageNumber){ctx.textAlign=state.pageNumberAlign;const x=state.pageNumberAlign==="left"?56:state.pageNumberAlign==="center"?PAGE_W/2:PAGE_W-56;ctx.fillText(String(pageIndex+1),x*scale,y)}}ctx.restore()}
  async function renderCanvas(pageIndex){const scale=2,canvas=document.createElement("canvas");canvas.width=PAGE_W*scale;canvas.height=PAGE_H*scale;const ctx=canvas.getContext("2d");ctx.fillStyle="#fff";ctx.fillRect(0,0,canvas.width,canvas.height);drawPageDecorations(ctx,pageIndex,scale);const blocks=state.blocks.filter(b=>(b.page||0)===pageIndex).sort((a,b)=>(a.type==="image"&&a.wrap==="behind"?-1:0)-(b.type==="image"&&b.wrap==="behind"?-1:0));for(const b of blocks){if(b.type==="image"){const image=await imageElement(b.src);drawImageInBox(ctx,image,b.x,b.y,b.w,b.h,scale,0,b.fit||"contain",b.positionX??50,b.positionY??50);continue}if(b.type==="table"){const columns=tableTracks(tableWeights(b.colWidths,b.cols),b.w),rows=tableTracks(tableWeights(b.rowHeights,b.rows),b.h);for(let index=0;index<(b.cells||[]).length;index++){if(cellIsHidden(b,index))continue;const region=cellRegion(b,index),rx=b.x+columns.offsets[region.col],ry=b.y+rows.offsets[region.row],rw=columns.offsets[region.col+region.colSpan]-columns.offsets[region.col],rh=rows.offsets[region.row+region.rowSpan]-rows.offsets[region.row],cellImage=b.cellImages?.[index];if(cellImage){const image=await imageElement(cellImage.src);drawImageInBox(ctx,image,rx,ry,rw,rh,scale,4)}drawCanvasText(ctx,b,b.cells[index],rx,ry,rw,rh,scale);ctx.save();ctx.strokeStyle="#7f9095";ctx.lineWidth=1.2*scale;ctx.strokeRect(rx*scale,ry*scale,rw*scale,rh*scale);ctx.restore()}}else{drawCanvasText(ctx,b,b.text,b.x,b.y,b.w,b.h,scale);if(b.border){ctx.save();ctx.strokeStyle="#9aa8ab";ctx.lineWidth=1.5*scale;ctx.strokeRect(b.x*scale+.75*scale,b.y*scale+.75*scale,b.w*scale-1.5*scale,b.h*scale-1.5*scale);ctx.restore()}}}return canvas}
  function makePdf(dataUrls){const images=dataUrls.map(dataUrl=>{const binary=atob(dataUrl.split(",")[1]),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return bytes}),pagePtW=state.orientation==="landscape"?841.89:595.28,pagePtH=state.orientation==="landscape"?595.28:841.89,enc=new TextEncoder(),chunks=[],offsets=[0];let offset=0;const push=x=>{const bytes=typeof x==="string"?enc.encode(x):x;chunks.push(bytes);offset+=bytes.length},obj=(id,body)=>{offsets[id]=offset;push(`${id} 0 obj\n`);typeof body==="function"?body():push(body);push("\nendobj\n")};push("%PDF-1.4\n");obj(1,"<< /Type /Catalog /Pages 2 0 R >>");const pageIds=images.map((_,i)=>3+i*3);obj(2,`<< /Type /Pages /Kids [${pageIds.map(id=>`${id} 0 R`).join(" ")}] /Count ${images.length} >>`);images.forEach((image,i)=>{const pageId=3+i*3,imageId=pageId+1,contentId=pageId+2,name=`Im${i}`;obj(pageId,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pagePtW} ${pagePtH}] /Resources << /XObject << /${name} ${imageId} 0 R >> >> /Contents ${contentId} 0 R >>`);obj(imageId,()=>{push(`<< /Type /XObject /Subtype /Image /Width ${PAGE_W*2} /Height ${PAGE_H*2} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${image.length} >>\nstream\n`);push(image);push("\nendstream")});const content=`q\n${pagePtW} 0 0 ${pagePtH} 0 0 cm\n/${name} Do\nQ`;obj(contentId,`<< /Length ${content.length} >>\nstream\n${content}\nendstream`)});const size=3+images.length*3,xref=offset;push(`xref\n0 ${size}\n0000000000 65535 f \n`);for(let i=1;i<size;i++)push(`${String(offsets[i]).padStart(10,"0")} 00000 n \n`);push(`trailer\n<< /Size ${size} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);const out=new Uint8Array(chunks.reduce((n,c)=>n+c.length,0));let pos=0;chunks.forEach(c=>{out.set(c,pos);pos+=c.length});return new Blob([out],{type:"application/pdf"})}
  async function exportPdf(){try{const title=$("doc-title").value||"A4文件",jpegs=[];for(let page=0;page<state.pageCount;page++)jpegs.push((await renderCanvas(page)).toDataURL("image/jpeg",.96));download(makePdf(jpegs),`${title}.pdf`);notify(`PDF 已匯出（${state.pageCount} 頁）`)}catch(error){console.error(error);notify("PDF 匯出失敗")}}
  $("export-word").onclick=e=>{e.stopPropagation();exportWord();$("export-menu").hidden=true}; $("export-pdf").onclick=e=>{e.stopPropagation();exportPdf();$("export-menu").hidden=true};
  $("open-templates").onclick=openTemplates;$("mobile-templates").onclick=e=>{e.stopPropagation();openTemplates()};$("close-templates").onclick=closeTemplates;$("template-scrim").onclick=closeTemplates;$("save-template").onclick=saveAsTemplate;$("template-name").addEventListener("keydown",e=>{if(e.key==="Enter")saveAsTemplate()});$("save-template-changes").onclick=saveTemplateChanges;
